// Replace this node with a real rank lookup (DataForSEO, SerpApi, ...).
//
// Contract (fix/geogrid-partial-runs): each item must output
// { idx, rank, measured }. `rank` is 1-20 or null. `measured` is true when
// the lookup for this point actually completed (regardless of whether it
// ranked) and false when it failed for this point alone -- a per-point
// failure must NOT throw out of this node, because that would fail the
// whole run for one bad point. Catch per-point errors here and emit
// { idx, rank: null, measured: false } for that point instead.
//
// `error` at the top level (see "Post ranks back" below) is reserved for a
// total failure -- nothing could be measured at all (e.g. the ranking API
// was unreachable for the whole run). Do not set it when even one point
// succeeded; a body carrying both `ranks` and `error` is treated upstream as
// the partial result it is, but every point you *can* report should be
// reported via `ranks` rather than folded into `error`.
return $input.all().map((item) => {
  try {
    // ... real lookup for item.json.idx / item.json.lat / item.json.lng ...
    const rank = null;
    return { json: { idx: item.json.idx, rank, measured: true } };
  } catch (e) {
    return { json: { idx: item.json.idx, rank: null, measured: false } };
  }
});

// Collect every per-point result into a single ranks array. Each entry
// keeps its idx, rank, and measured flag -- see the contract note on the
// lookup node above.
return [{
  json: {
    data: $input.all().map((i) => ({
      idx: i.json.idx,
      rank: i.json.rank ?? null,
      measured: i.json.measured !== false,
    })),
  },
}];
